/bin/zsh -lc "mkdir -p drafts
node --input-type=module <<'NODE'
import { readFile, writeFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { parseDocument } from './scripts/vendor/yaml.mjs';
const hash = s => 'sha256:' + createHash('sha256').update(s).digest('hex');
const design = await readFile('DESIGN.md', 'utf8');
const tokens = await readFile('.template-spec/design/tokens/variables.css', 'utf8');
const dataBytes = await readFile('fixture/data.json', 'utf8');
const data = JSON.parse(dataBytes);
const front = parseDocument(design.split('---')[1]).toJS();
const kebab = s => s.replace(/[A-Z]/g, c => '-' + c.toLowerCase());
const lines = [];
function visit(value, path) {
  if (value && typeof value === 'object') { for (const [k, v] of Object.entries(value)) visit(v, [...path,k]); }
  else if (typeof value === 'string' || typeof value === 'number') {
    const css = String(value).replace(/\\{(["'^}]+)'"\\}/g, (_, ref) => 'var(--design-' + ref.split('.').map(kebab).join('-') + ')');
    if ("'!['"'typography'].includes(path.at(-1))) lines.push('  --design-' + path.map(kebab).join('-') + ': ' + css + ';');
  }
}
for (const key of ['colors','typography','rounded','spacing','components']) visit(front[key], [key]);
await writeFile('drafts/tokens.css', tokens);
await writeFile('drafts/design-tokens.css', '/* Derived from root DESIGN.md; fixture-local semantic roles. */\\n:root {\\n' + lines.join('\\n') + '\\n}\\n');
await writeFile('drafts/scenarios.js', '/* fixture/data.json copied as offline data; no request or storage required. */\\nwindow.fixtureRecords = ' + JSON.stringify(data, null, 2) + ';\\nwindow.prototypeScenarios = [\\n  { id: \"primary\", label: \"正常保存\", hint: \"编辑名称与负责人后保存，查看保存结果。\" },\\n  { id: \"failure\", label: \"保存失败\", hint: \"首次保存模拟失败，输入保留；重试后成功。\" },\\n  { id: \"conflict\", label: \"并发冲突\", hint: \"首次保存触发冲突；主动重新加载当前版本后可再次保存。\" }\\n];\\n');
await writeFile('drafts/yss-prototype-adapter.json', JSON.stringify({schema_version:4,feature:'conflict-recovery',pattern:'editor',prototype_profile:'H2',profile_kind:'flow-review',component_basis:'html-css-js',runtime_build_required:false,entry:'index.html',design_source:{path:'DESIGN.md',digest:hash(design)},token_source:{path:'.template-spec/design/tokens/variables.css',digest:hash(tokens)},fixture_source:{path:'fixture/data.json',digest:hash(dataBytes)},fixture_only:true,files:{}}, null, 2) + '\\n');
console.log('已生成 drafts/ 本地 Token、场景数据与来源摘要。');
NODE"

